from h34 import *
M=mcq;F=tf;S=short;N=num
chapter(3,'evs','taking-charge-of-waste','Taking Charge of Waste',
 ('A clean school, a clean town','On National Cleanliness Day, 30 January, a class pledges to keep itself and its surroundings clean. The children look around and ask: where does all our waste come from, and where does it go? This chapter shows how waste is created, why it harms animals and people, how we can reduce, reuse and recycle, and how some villages and cities manage their waste so well.'),
 [('How waste is created',['Waste is the things we throw away because we no longer need them, such as old clothes, tins, bottles, paper, fruit and vegetable peels, plastic wrappers, pencil shavings and used batteries.','Every home, school and market makes waste every day.','When we make too much waste and throw it carelessly, our surroundings become dirty.']),
  ('Why waste is harmful',['Waste thrown on the ground or into water makes places dirty and smelly.','Animals can be hurt when they eat plastic or get caught in it.','Rotting waste and dirty places spread germs and make people ill.','So we must manage our waste properly.']),
  ('Reduce and reuse',['To reduce means to make less waste, for example by carrying a cloth bag instead of taking a new plastic bag.','To reuse means to use a thing again, for example by using an old jar to store things.','Our aim is Want not, Waste not, which means we should not waste things we do not need.']),
  ('Separate your waste',['Dustbins of two colours are kept in schools, markets, parks, bus stands, railway platforms and melas.','The green dustbin is for waste that rots easily, such as dried leaves, fruit peels, vegetable waste and eggshells. This waste mixes with the soil and becomes compost, which is food for plants and tiny animals in the soil.','The blue dustbin is for things made of metal, glass, plastic and paper. New objects can be made from them again, and this is called recycling.','Sharp things like broken glass and needles must be wrapped in cloth and paper so that sanitation workers are not hurt.']),
  ('A place of pride',['Some villages and towns separate and recycle their waste and keep their surroundings clean. They manage waste well.','Silluk in Arunachal Pradesh and Chhota Narena are villages known for managing their waste.','Indore and Mysuru are cities known for being clean.','Each one of us can help keep our home, neighbourhood, school, city and country clean.'])],
 [('Which bin do these go into: banana peel, glass bottle, eggshell, newspaper?',[('Banana peel and eggshell rot and mix with soil.','They go in the green bin.'),('Glass bottle and newspaper can be made into new things.','They go in the blue bin.'),('Wrap any broken glass before throwing it.','This keeps workers safe.')]),
  ('How can we have a zero-waste birthday party?',[('Think what waste a party makes: plastic plates, wrappers, balloons.','First find the waste.'),('Use steel or cloth things and reuse them.','This reduces waste.'),('Put peels in the green bin and bottles in the blue bin.','Sort what is left.')])],
 ('Explain how we can manage waste.',['Make less waste','Reuse things','Green bin for peels and leaves','Blue bin for metal, glass, plastic, paper'],['All waste goes in one bin','Throwing waste anywhere is fine']),
 ['Waste is made in every home, school and market.','Careless waste harms animals, people and places.','Reduce, reuse and recycle.','Green bin: waste that rots. Blue bin: metal, glass, plastic, paper.','Want not, Waste not.'],
 [M('1',1,'Which bin is for fruit peels?','Green',[('Blue','Blue is for metal, glass, plastic, paper'),('Red','Not used here')],'Peels rot and go in the green bin.'),
  M('2',1,'Which bin is for plastic bottles?','Blue',[('Green','Green is for waste that rots'),('Neither','They can be recycled')],'Plastic goes in the blue bin.'),
  M('3',1,'When is National Cleanliness Day?','30 January',[('15 August','That is Independence Day'),('2 October','That is Gandhi Jayanti')],'It is on 30 January.'),
  M('4',1,'What does recycling mean?','Making new things from thrown away materials',[('Burning waste','Not recycling'),('Burying waste','Not recycling')],'Recycling makes new objects from old material.'),
  M('5',2,'What does waste in the green bin become?','Compost',[('Plastic','It rots into compost'),('Glass','It rots into compost')],'Rotting waste becomes compost, food for plants.'),
  F('6',2,'Eggshells go in the green bin.',True,'Eggshells rot and mix with soil.'),
  F('7',2,'Broken glass can be thrown loose.',False,'It must be wrapped so workers are not hurt.'),
  M('8',2,'Which is a way to reduce waste?','Using a cloth bag again and again',[('Buying a new plastic bag each time','That makes more waste'),('Throwing paper on the road','That is careless')],'A cloth bag reduces plastic waste.'),
  M('9',2,'Why is careless waste harmful?','It can hurt animals and spread illness',[('It makes plants taller','It does not'),('It makes the air sweet','It does not')],'Waste harms animals and health.'),
  S('10',2,'What do we call using a thing again?',['reuse','Reuse','re-use'],'To reuse is to use again.'),
  M('11',3,'Which city is named in the chapter as clean?','Indore',[('Delhi','Not named in this chapter'),('Kolkata','Not named in this chapter')],'Indore and Mysuru are named.'),
  M('12',3,'What does Want not, Waste not teach?','Do not waste what you do not need',[('Buy more things','The opposite'),('Throw things quickly','The opposite')],'It teaches us not to waste.')],
 keep=['recycle','compost'])
